prompt --application/pages/page_00004
begin
wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'Import & Select PGMOPTs'
,p_step_title=>'Import & Select PGMOPTs'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Because this page has an Interactive Report, this jQuery has to be in 2 places. Here''s the explanation why:',
'',
'   "Filtering an Oracle APEX Interactive Report typically involves an AJAX request ',
'    to the server to re-render the report based on the applied filters. This partial',
'    page refresh can sometimes interfere with or "inactivate" JavaScript code that',
'    was executed during the initial page load, particularly if that JavaScript targets',
'    elements within the Interactive Report region."',
'   ',
'   So we put the code:',
'',
'   1. Here when page loads so that the "Select All" box works when the page loads, and',
'   2. As a Dynamic Action after the Interactive Report refreshes (like after a filter is applied),',
'      otherwise the Select All stops working when other filters are applied',
'*/',
'//select all checkboxes',
'$("#select_all").change(function(){  //"select all" change ',
'    $(".my_checkbox").prop(''checked'', $(this).prop("checked")); //change all ".my_checkbox" checked status',
'});',
'',
'//".my_checkbox" change ',
'',
'$(''.my_checkbox'').change(function(){ ',
'	//uncheck "select all", if one of the listed checkbox item is unchecked',
' ',
'    if(false == $(this).prop("checked")){ //if this item is unchecked',
'        $("#select_all").prop(''checked'', false); //change "select all" checked status to false',
'    }',
'    ',
'	//check "select all" if all checkbox items are checked',
'	if ($(''.my_checkbox:checked'').length == $(''.my_checkbox'').length ){',
'		$("#select_all").prop(''checked'', true);',
'	}',
'',
'});'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(235989414114015446778)
,p_plug_name=>'Program Options (&AI_REMOTE_ENV.)'
,p_region_template_options=>'#DEFAULT#:t-Region--accent9:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
'            ,p_n001    => c1.ID',
'            ,p_n002    => c1.app_id',
'            ,p_c001    => c1.app_alias',
'            ,p_n003    => c1.opt_no',
'            ,p_c002    => c1.opt_name ',
'            ,p_c003    => c1.opt_val_varchar',
'            ,p_n004    => c1.opt_val_number',
'            ,p_c004    => c1.opt_val_boolean',
'            ,p_c005    => c1.opt_val_date',
'            ,p_d001    => to_date( c1.opt_val_date, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' ) ',
'            ,p_c006    => c1.opt_val_timestamp',
'            ,p_clob001 => c1.opt_val_clob );',
'*/',
'select ',
'     n001    ID',
'    ,APEX_ITEM.CHECKBOX2(1,SEQ_ID,''class="my_checkbox"'',NULL,NULL,''f01_''||SEQ_ID) as select_row',
'    ,n002    app_id',
'    ,c001    app_alias',
'    ,n003    opt_no',
'    ,c002    opt_name ',
'    ,c003    opt_val_varchar',
'    ,n004    opt_val_number',
'    ,c004    opt_val_boolean',
'    ,c005    opt_val_date',
'    ,to_char( d001, ''MM-DD-YYYY HH:MI:SS pm'') as opt_val_date_formatted ',
'    ,c006    opt_val_timestamp',
'    ,clob001 opt_val_clob',
'    ,''* Remote Images Not Displayed *'' as imagej',
'    ,d005    eff_start_da',
'    ,c015    eff_end_da',
'/*',
'   x.ID',
'  ,APEX_ITEM.CHECKBOX2(1,x.ID,''class="my_checkbox"'',NULL,NULL,''f01_''||x.ID) as select_row',
'  ,x.app_id',
'  ,x.app_alias',
'  ,x.opt_no',
'  ,x.opt_name  -- looks like JSON output gets escaped by default',
'  ,x.opt_val_varchar',
'  ,x.opt_val_number',
'  ,x.opt_val_boolean',
'  ,x.opt_val_clob',
'  ,x.opt_val_date',
'  ,to_char(to_date( x.opt_val_date, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' ),''MM-DD-YYYY HH:MI:SS pm'') as opt_val_date_formatted',
'  ,x.opt_val_timestamp',
'  ,''* Images Cannot be Copied *'' as image',
'*/',
'--   ,apxshr_package.convert_json_text(x.OPT_VAL_CLOB, ''FROM'') OPT_VAL_CLOB    -- may not be necessary. Looks like JSON is automaticall escaped and un-escaped by these processes',
'from apex_collections /* c, ',
'     xmltable (',
'         ''/json/items/row''',
