wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(234606657581705427186)
,p_event_id=>wwv_flow_imp.id(234606657038461427184)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'REGION'
,p_affected_region_id=>wwv_flow_imp.id(235989414114015446778)
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Because this page has an Interactive Report, this jQuery has to be in 2 places. Here''s the explanation why:',
'',
'   "Filtering an Oracle APEX Interactive Report typically involves an AJAX request ',
'    to the server to re-render the report based on the applied filters. This partial',
'    page refresh can sometimes interfere with or "inactivate" JavaScript code that',
'    was executed during the initial page load, particularly if that JavaScript targets',
'    elements within the Interactive Report region."',
'   ',
'   So we put the code:',
'',
'   1. Here when page loads so that the "Select All" box works when the page loads, and',
'   2. As a Dynamic Action after the Interactive Report refreshes (like after a filter is applied),',
'      otherwise the Select All stops working when other filters are applied',
'*/',
'//select all checkboxes',
'$("#select_all").change(function(){  //"select all" change ',
'    $(".my_checkbox").prop(''checked'', $(this).prop("checked")); //change all ".my_checkbox" checked status',
'});',
'',
'//".my_checkbox" change ',
'',
'$(''.my_checkbox'').change(function(){ ',
'	//uncheck "select all", if one of the listed checkbox item is unchecked',
' ',
'    if(false == $(this).prop("checked")){ //if this item is unchecked',
'        $("#select_all").prop(''checked'', false); //change "select all" checked status to false',
'    }',
'    ',
'	//check "select all" if all checkbox items are checked',
'	if ($(''.my_checkbox:checked'').length == $(''.my_checkbox'').length ){',
'		$("#select_all").prop(''checked'', true);',
'	}',
'',
'});'))
);
