wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(234606656649176427183)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch Data Into Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_response clob;',
'    l_default_endpoint VARCHAR2(1000) := ''https://apex.mydomain.com:7170/apex/data_services/pgmopt/options/by_alias/'';',
'    l_parameter VARCHAR2(100) := q''#TEST#'';',
'    my_json clob;',
'    my_json_t apex_json.t_values;',
'    l_paths apex_t_varchar2;    ',
'    l_context       apex_exec.t_context; ',
'    ',
'FUNCTION get_MYAUTH return varchar2 is     ',
'      ',
'  l_cookie owa_cookie.cookie;     ',
'  l_MYAUTH varchar2(255);     ',
'      ',
'BEGIN     ',
'  begin     ',
'    l_cookie := owa_cookie.get(''MYAUTH'');     ',
'    l_MYAUTH := l_cookie.vals(1);     ',
'    l_MYAUTH := replace(l_MYAUTH,CHR(34));     ',
'      ',
'    exception when no_data_found then l_MYAUTH := ''No MYAUTH Cookie'';     ',
'  end;     ',
'      ',
'  RETURN l_MYAUTH;  ',
'END get_MYAUTH;',
'',
'begin',
'--    if APXSHR_PACKAGE.staging_port ',
'    if :AI_LOCAL_ENV = ''STAGING''',
'--    if g_url_port = ''7170''  ',
'--    or g_url_port = ''7670''    ',
'    then',
'        -- running in STAGING, get PGMOPTS from PRODUCTION',
'        l_default_endpoint := APXSHR_PGM_OPTS.rtn_pgm_opt (''PGMOPT'', 2, ''text''); --''http://apexp.mydomain.com:7070/apex/hq001/pgmopt/options/by_alias/'';   ',
'--        l_default_endpoint := ''http://apexp.mydomain.com:7070/apex/hq001/pgmopt/options/all_options2'';  -- testing',
'--    elsif APXSHR_PACKAGE.production_port',
'    elsif :AI_LOCAL_ENV = ''PRODUCTION''',
'--    elsif g_url_port = ''7070''',
'--       or g_url_port = ''7570''',
'    then',
'        -- running in PRODUCTION, get PGMOPTS from STAGING',
'        l_default_endpoint := APXSHR_PGM_OPTS.rtn_pgm_opt (''PGMOPT'', 3, ''text''); -- ''http://apexp.mydomain.com:7170/apex/hq001/pgmopt/options/by_alias/'';',
'    end if;',
'    ',
'    l_parameter := :P4_APP_ALIAS;  -- use Page Item Value for search.',
'    ',
'    :P4_THIS_URL := case ',
'                          -- TODO: replace with your page item names here',
'                          when :P4_SHOW_PAGE = ''next'' and :P4_URL_NEXT_PAGE is not null then :P4_URL_NEXT_PAGE',
'                          when :P4_SHOW_PAGE = ''prev'' and :P4_URL_PREV_PAGE is not null then :P4_URL_PREV_PAGE',
'--                          else nvl( :P4_THIS_URL, l_default_endpoint||''?my_alias=''|| sys.utl_url.escape(l_parameter))  -- :P4_SAMPLE_ENDPOINT_URL )  -- 5.1, use "?parameter_name="',
'                          else nvl( :P4_THIS_URL, l_default_endpoint || sys.utl_url.escape(l_parameter) )  -- :P4_SAMPLE_ENDPOINT_URL )  -- 19.2 use "parameter_value"',
'                          -- AFTER 19.2, using "?my_alias=" doesn''t work.  Just provide the parameter value after the endpoing, but the endpoing must end in a ''/''',
'                          -- This: ''http://apexp.mydomain.com:7070/apex/hq001/pgmopt/options/by_alias/BTG''',
'                          -- NOT this: ''http://apexp.mydomain.com:7070/apex/hq001/pgmopt/options/by_alias/?my_alias=BTG''',
'                      end;',
'                      ',
'    apex_debug.info(''P4_THIS_URL=%s'',:P4_THIS_URL);                      ',
'',
'    :P4_SHOW_PAGE := null;',
'    ',
'    -- Set HTTP Request Headers',
'    apex_web_service.g_request_headers.delete;',
'',
'    apex_web_service.g_request_headers(1).name  := q''#My_Alias#'';',
'    ',
'    apex_debug.info(''l_parameter=%s. MYAUTH=%s. page=%s'', l_parameter, get_MYAUTH(), :P4_THIS_URL);',
'    ',
'    apex_web_service.g_request_headers(1).value := l_parameter;',
'--    apex_web_service.g_request_headers(2).name  := q''#MYAUTH#'';',
'--    apex_web_service.g_request_headers(2).value := get_MYAUTH ();   ',
'--    apex_web_service.g_request_headers(3).name  := ''page'';',
'--    apex_web_service.g_request_headers(3).value := :P4_THIS_URL;   ',
'    apex_web_service.g_request_headers(2).name  := ''page'';',
'    apex_web_service.g_request_headers(2).value := :P4_THIS_URL;       ',
'',
'    -- load REST response into a collection',
'    l_response := apex_web_service.make_rest_request (',
'        p_url => :P4_THIS_URL,',
'--        p_https_host => '''',  -- May be needed in future. As of 8/12/21 this didn''t work       ',
'        p_http_method      => ''GET'') ;',
'',
'    --apex_debug.info(''l_response=%s'',l_response);',
'',
'    -- create & populate collection with JSON response',
'    apex_collection.create_or_truncate_collection( ''P4_REST_RESULTS'' );',
'    apex_collection.add_member(',
'        p_collection_name => ''P4_REST_RESULTS'',',
'        p_clob001 =>         l_response );',
'',
'--  initialize the links',
'    :P4_URL_NEXT_PAGE := NULL;',
'    :P4_URL_PREV_PAGE := NULL;    ',
'    ',
'--  set pagination variables',
'/*  Old way - APEX REST Services',
'    select',
'        x.next_page, ',
'        coalesce( x.prev_page, x.previous_page ) ',
'      -- TODO: replace with your page item names here',
'      into :P4_URL_NEXT_PAGE, :P4_URL_PREV_PAGE',
'    from apex_collections c, xmltable( ',
'        ''/json''',
'        passing apex_json.to_xmltype( c.clob001 )',
'        columns',
'            next_page     varchar2(500) path ''next/_ref'',',
'            prev_page     varchar2(500) path ''prev/_ref'',',
'            previous_page varchar2(500) path ''previous/_ref''',
'    ) x',
'    where c.collection_name = ''P4_REST_RESULTS'';',
'*/   ',
'--  Parse the json return',
'    apex_json.parse(my_json_t, l_response);',
'--  Get NEXT link    ',
'    l_paths := apex_json.find_paths_like (',
'        p_values         => my_json_t,',
'        p_return_path => ''links[%]'',',
'        p_subpath       => ''.rel'',',
'        p_value           => ''next'' );',
'',
'    apex_debug.info(''1st l_paths.count=%'',l_paths.count);',
'    ',
'    for i in 1 .. l_paths.count ',
'    loop',
'        :P4_URL_NEXT_PAGE := apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href'') ;        ',
'--        dbms_output.put_line(apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href'')); ',
'        apex_debug.info(apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href''));',
'    end loop;    ',
'    ',
'    apex_debug.info('':P4_URL_NEXT_PAGE=%s'',:P4_URL_NEXT_PAGE);  ',
'    ',
'--    apex_json.parse(my_json_t, l_response);',
'--  Get PREV link',
'    l_paths := apex_json.find_paths_like (',
'        p_values         => my_json_t,',
'        p_return_path => ''links[%]'',',
'        p_subpath       => ''.rel'',',
'        p_value           => ''prev'' );',
'',
'    apex_debug.info(''2nd l_paths.count=%'',l_paths.count);        ',
'    ',
'    for i in 1 .. l_paths.count ',
'    loop',
'--        :P4_URL_PREV_PAGE := :P4_URL_PREV_PAGE || apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href'') ;',
'        :P4_URL_PREV_PAGE := apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href'') ;        ',
'        dbms_output.put_line(apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href'')); ',
'        apex_debug.info(apex_json.get_varchar2(p_values => my_json_t, p_path => l_paths(i)||''.href''));',
'    end loop;    ',
'    ',
'    apex_debug.info('':P4_URL_PREV_PAGE=%s'',:P4_URL_PREV_PAGE);  ',
'',
'--  create collection for parsed results',
'    apex_collection.create_or_truncate_collection( ''P4_PARSED_RESULTS'' );',
'',
'--  parse results into new collection    ',
'    for c1 in (',
'                select ',
'                   x.ID',
'                  ,x.app_id',
'                  ,x.app_alias',
'                  ,x.opt_no',
'                  ,x.opt_name  -- looks like JSON output gets escaped by default, no need to "un-parse"',
'                  ,x.opt_val_varchar',
'                  ,x.opt_val_number',
'                  ,x.opt_val_boolean',
'                  ,x.opt_val_clob',
'                  ,x.opt_val_date',
'     --             ,to_char(to_date( x.opt_val_date, ''YYYY-MM-DD HH24:MI:SS'' ),''MM-DD-YYYY HH:MI:SS pm'') as opt_val_date_formatted',
'                  ,to_char(to_date( x.opt_val_date, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' ),''MM-DD-YYYY HH:MI:SS pm'') as opt_val_date_formatted                  ',
'                  --''YYYY-MM-DD"T"HH24:MI:SS"Z"''',
' --                 ,to_char(to_timestamp( x.opt_val_timestamp, ''DD-MON-YY HH24:MI:SS:FF''), ''MM-DD-YYYY HH:MI:SS pm'') as opt_val_timestamp',
'                  ,x.opt_val_timestamp',
'                  ,x.opt_val_img',
'                  ,x.img_file_name',
'                  ,x.img_mime_type',
'                  ,x.img_char_set',
'                  ,x.img_last_upd_da ',
'                  ,x.eff_start_da',
'                  ,x.eff_end_da',
'                --  ,apxshr_package.convert_json_text(x.OPT_VAL_CLOB, ''FROM'') as OPT_VAL_CLOB    -- may not be necessary. Looks like JSON is automaticall escaped and un-escaped by these processes',
'                from apex_collections c, ',
'                     xmltable (',
'                         ''/json/items/row''',
'                         passing apex_json.to_xmltype( c.clob001 )',
'                         columns',
'                           ID  NUMBER    path ''id''',
'                          ,app_id  NUMBER    path ''app_id''',
'                          ,app_alias  VARCHAR2(100)   path ''app_alias''',
'                          ,opt_no  NUMBER    path ''opt_no''',
'                          ,opt_name   VARCHAR2(100)   path ''opt_name''',
'                          ,opt_val_varchar VARCHAR2(4000)   path ''opt_val_varchar''',
'                          ,opt_val_number  NUMBER   path ''opt_val_number''',
'                          ,opt_val_boolean VARCHAR2(100)  path ''opt_val_boolean''',
'                          ,opt_val_clob  CLOB path ''opt_val_clob''',
'                          ,opt_val_date  VARCHAR2(100)  path ''opt_val_date''',
'                          ,opt_val_timestamp VARCHAR2(100)  path ''opt_val_timestamp''',
'                          ,opt_val_img CLOB path ''opt_val_img''',
'                          ,img_file_name VARCHAR2(4000) path ''img_file_name''',
'                          ,img_mime_type VARCHAR2(100) path ''img_mime_type''',
'                          ,img_char_set VARCHAR2(100) path ''img_char_set''',
'                          ,img_last_upd_da VARCHAR2(100) path ''img_last_upd_da''',
'                          ,eff_start_da VARCHAR2(100) path ''eff_start_da''',
'                          ,eff_end_da VARCHAR2(100) path ''eff_end_da''',
'                              ) x',
'                where c.collection_name = ''P4_REST_RESULTS''',
'              )',
'    loop',
'        apex_collection.add_member(',
'             p_collection_name => ''P4_PARSED_RESULTS''',
'            ,p_n001    => c1.ID',
'            ,p_n002    => c1.app_id',
'            ,p_c001    => c1.app_alias',
'            ,p_n003    => c1.opt_no',
'            ,p_c002    => c1.opt_name ',
'            ,p_c003    => c1.opt_val_varchar',
'            ,p_n004    => c1.opt_val_number',
'            ,p_c004    => c1.opt_val_boolean',
'            ,p_c005    => c1.opt_val_date',
'            --,p_d001    => to_date( c1.opt_val_date, ''YYYY-MM-DD HH24:MI:SS'' ) ',
'            ,p_d001    => to_date( c1.opt_val_date, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' )             ',
'            ,p_c006    => c1.opt_val_timestamp',
'            ,p_clob001 => c1.opt_val_clob ',
'            ,p_blob001 => APEX_WEB_SERVICE.CLOBBASE642BLOB ( p_clob => c1.opt_val_img )',
'            ,p_c007    => c1.img_mime_type',
'            ,p_c008    => c1.img_file_name',
'            ,p_c009    => c1.img_char_set',
'            ,p_c010    => c1.img_last_upd_da',
'            ,p_d002    => to_date( c1.img_last_upd_da, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' )',
'            ,p_d005    => to_date( c1.eff_start_da, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'' )',
'            ,p_c015    => c1.eff_end_da',
'            );',
'    end loop;',
'    ',
'-- APEX won''t let us use the secure port to request the REST service',
'/*',
'    :P4_URL_NEXT_PAGE := replace (:P4_URL_NEXT_PAGE, ''https://'',''http://''); --''http://apexp.mydomain.com:7170/apex/hq001/pgmopt/options/by_alias/RAA?page=1'';',
' --   :P4_URL_NEXT_PAGE := replace (:P4_URL_NEXT_PAGE, '':7670/'','':7170/'');    ',
' --   :P4_URL_NEXT_PAGE := replace (:P4_URL_NEXT_PAGE, '':7570/'','':7070/'');   ',
'    :P4_URL_PREV_PAGE := replace (:P4_URL_PREV_PAGE, ''https://'',''http://''); --''http://apexp.mydomain.com:7170/apex/hq001/pgmopt/options/by_alias/RAA?page=1'';',
' --   :P4_URL_PREV_PAGE := replace (:P4_URL_PREV_PAGE, '':7670/'','':7170/'');    ',
' --   :P4_URL_PREV_PAGE := replace (:P4_URL_PREV_PAGE, '':7570/'','':7070/'');          ',
'*/',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>3550559628483576519
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(234606656291249427182)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert / Update Selected Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_update_count NUMBER :=0;',
'    l_insert_count NUMBER :=0;',
'    l_commit_count NUMBER :=0;',
'    l_x VARCHAR2(10);',
'  ',
'    l_app_id NUMBER;',
'    l_app_alias APXSHR_PGM_OPTIONS.APP_ALIAS%TYPE;',
'    l_opt_no NUMBER;',
'    l_opt_name APXSHR_PGM_OPTIONS.OPT_NAME%TYPE;',
'    l_opt_val_varchar APXSHR_PGM_OPTIONS.OPT_VAL_VARCHAR%TYPE;',
'    l_opt_val_number NUMBER;',
'    l_opt_val_boolean APXSHR_PGM_OPTIONS.OPT_VAL_BOOLEAN%TYPE;',
'    l_opt_val_date DATE;',
'    l_opt_val_timestamp TIMESTAMP;',
'    l_opt_val_clob CLOB;',
'    l_opt_val_img BLOB;',
'    l_img_mime_type APXSHR_PGM_OPTIONS.IMG_MIME_TYPE%TYPE;',
'    l_img_file_name APXSHR_PGM_OPTIONS.IMG_FILE_NAME%TYPE;',
'    l_img_char_set APXSHR_PGM_OPTIONS.IMG_CHAR_SET%TYPE;',
'    l_img_last_upd_da DATE;',
'    l_eff_start_da DATE; ',
'    l_eff_end_da DATE; ',
'',
'BEGIN',
'    FOR I in 1..APEX_APPLICATION.G_F01.COUNT -- repeat for each selected checkbox',
'    LOOP',
'',
'        begin -- select',
'            select',
'             --   N002,     C001,        N003,       C002,       C003,              N004,             C004,              D001,           TO_TIMESTAMP(C006,''YYYY-MM-DD HH24:MI:SS.FF''), CLOB001 ',
'                N002,     C001,        N003,       C002,       C003,              N004,             C004,              D001,           TO_TIMESTAMP(C006,''YYYY-MM-DD"T"HH24:MI:SS"Z"''), CLOB001,',
'                BLOB001,  C007,        C008,       C009,       D002,              D005,             to_date (C015, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'')              ',
'                -- ''YYYY-MM-DD"T"HH24:MI:SS"Z"''',
'              into',
'                l_app_id, l_app_alias, l_opt_no,   l_opt_name, l_opt_val_varchar, l_opt_val_number, l_opt_val_boolean, l_opt_val_date, l_opt_val_timestamp,                             l_opt_val_clob,',
'                l_opt_val_img, l_img_mime_type, l_img_file_name, l_img_char_set, l_img_last_upd_da, l_eff_start_da, l_eff_end_da',
'            from APEX_COLLECTIONS ',
'            where COLLECTION_NAME = ''P4_PARSED_RESULTS''',
'              and SEQ_ID = APEX_APPLICATION.G_F01(I);',
'        end;  -- select',
'        ',
'        begin -- select APXSHR_PGM_OPTIONS row based on value in collection',
'            select ',
'              ''x'' into l_x',
'            from APXSHR_PGM_OPTIONS ',
'            where NVL(APP_ID, -1)      = nvl(l_app_id, -1)',
'              and NVL(APP_ALIAS, ''-1'') = nvl(l_app_alias, ''-1'')',
'              and OPT_NO               = l_opt_no;',
'            ',
'            -- if found, update the row',
'            begin --update',
'                update APXSHR_PGM_OPTIONS',
'                    set opt_name          = l_opt_name,',
'                        opt_val_varchar   = l_opt_val_varchar,',
'                        opt_val_number    = l_opt_val_number,',
'                        opt_val_boolean   = l_opt_val_boolean,',
'                        opt_val_date      = l_opt_val_date,',
'                        opt_val_timestamp = l_opt_val_timestamp,',
'                        opt_val_clob      = l_opt_val_clob,',
'                        opt_val_img       = l_opt_val_img,',
'                        img_mime_type     = l_img_mime_type,',
'                        img_char_set      = l_img_char_set,',
'                        img_file_name     = l_img_file_name,',
'                        img_last_upd_da   = l_img_last_upd_da,',
'                        eff_start_da      = l_eff_start_da,',
'                        eff_end_da        = l_eff_end_da ',
'                where NVL(APP_ID, -1)      = nvl(l_app_id, -1)',
'                  and NVL(APP_ALIAS, ''-1'') = nvl(l_app_alias, ''-1'')',
'                  and OPT_NO               = l_opt_no;',
'',
'                l_commit_count := l_commit_count + 1;',
'                l_update_count := l_update_count + 1;',
'                ',
'                -- exception when others then null;',
'            ',
'            end;  --update',
'              ',
'            exception ',
'                when NO_DATA_FOUND  -- if not found, INSERT the row',
'                then',
'                    begin -- insert',
'                        insert into APXSHR_PGM_OPTIONS',
'                            (app_id,   app_alias,   opt_no,     opt_name,   opt_val_varchar,   opt_val_number,   opt_val_boolean,   opt_val_date,   opt_val_timestamp,   opt_val_clob, opt_val_img, img_mime_type, img_file_name, img_char_set, img_last_u'
||'pd_da, eff_start_da, eff_end_da)',
'                        values',
'                            (l_app_id, l_app_alias, l_opt_no,   l_opt_name, l_opt_val_varchar, l_opt_val_number, l_opt_val_boolean, l_opt_val_date, l_opt_val_timestamp, l_opt_val_clob, l_opt_val_img, l_img_mime_type, l_img_file_name, l_img_char_set, '
||'l_img_last_upd_da, l_eff_start_da, l_eff_end_da);',
'                        ',
'                        l_insert_count := l_insert_count + 1;',
'                        l_commit_count := l_commit_count + 1;',
'                        ',
'                        exception when others then NULL;',
'                    end;  -- insert',
'                    ',
'',
'        end;  -- select',
'',
'        if l_commit_count > 50',
'        then',
'            COMMIT;',
'            l_commit_count := 0;',
'        end if;',
'',
'    END LOOP;',
'    ',
'   :P4_ROWS_UPDATED  := to_char(l_update_count,''99,990'');',
'   :P4_ROWS_INSERTED := to_char(l_insert_count,''99,990'');',
'',
'    COMMIT;',
'    ',
'END;  -- anonymous block'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(234606649276983427155)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'&P4_ROWS_UPDATED. Option(s) updated.',
'&P4_ROWS_INSERTED. Option(s) inserted.'))
,p_internal_uid=>3550559270556576518
);
end;
