,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add Alt Owner to ALIAS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_alias APXSHR_PGM_OPTIONS.APP_ALIAS%TYPE;',
'begin',
'    begin',
'        select APP_ALIAS into l_alias',
'        from APXSHR_PGM_OPTIONS',
'        where ID = :P5_OPTION_ID;',
'',
'        exception when OTHERS then l_alias := NULL;',
'    end;',
'',
'    if l_alias is NOT NULL',
'    then',
'        for C1 in (',
'            select',
'                ID',
'            from APXSHR_PGM_OPTIONS',
'            where APP_ALIAS = l_alias',
'        )',
'        loop',
'            begin -- insert',
'                insert into APXSHR_PGM_OPT_ALT_OWNR',
'                    (OPTION_ID, ALT_OWNR_ACF2_LID_ID)',
'                values',
'                    (C1.ID, :P5_ALT_OWNR_ACF2_LID_ID);',
'',
'                exception when OTHERS then NULL; -- this will ignore dups',
'            end; -- insert',
'        end loop;',
'',
'        COMMIT;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(234569447845831819362)
