,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4072363345357175094
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(231170637515630383576)
,p_plug_name=>'LOCAL Program Options (&AI_LOCAL_ENV.)'
,p_region_name=>'localOptions2'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:t-Region--hideShowIconsMath:is-expanded:t-Region--accent3:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2664334895415463485
,p_plug_display_sequence=>25
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'     n001    ID',
'    ,APEX_ITEM.CHECKBOX2(1,SEQ_ID,''class="my_checkbox"'',NULL,NULL,''f01_''||SEQ_ID) as select_row',
'    ,n002    app_id',
'    ,c001    app_alias',
'    ,n003    opt_no',
'    ,c002    opt_name ',
'    ,c003    opt_val_varchar',
'    ,n004    opt_val_number',
'    ,c004    opt_val_boolean',
'    ,c005    opt_val_date',
'    ,to_char( d001, ''MM-DD-YYYY HH:MI:SS pm'') as opt_val_date_formatted ',
'    ,c006    opt_val_timestamp',
'    ,clob001 opt_val_clob',
'--    ,''* Images will be copied *'' as image',
'-- since this image will be for a LOCAL table, we can display it',
'    , NVL2( BLOB001,',
'            ''<img src="'' || APEX_UTIL.GET_BLOB_FILE_SRC(''P12_OPT_VAL_IMG'', n001) ||',
'            ''" height="100" width="100" />'',',
'            ''No Image'') as image   ',
'    ,dbms_lob.getlength(BLOB001) as image_size             ',
'    ,dbms_lob.getlength(BLOB001) as image2                 ',
'    ,c008   img_file_name ',
'',
'    ,d003 as CREATED',
'    ,c012 as CREATED_BY',
'    ,d004 as UPDATED     ',
'    ,c014 as UPDATED_BY   ',
'    ,D005 as EFF_START_DA ',
'    ,to_date(C015, ''YYYY-MM-DD HH24:MI:SS'') as EFF_END_DA -- "VARCHAR" in collection since we only have 5 date columns  ',
'from apex_collections ',
'where collection_name = :AI_LOCAL_COLLECTION -- ''LOCAL_REST_SOURCE_RESULTS''',
'order by n002, c001, n003  -- app_id, app_alias, opt_no'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from apex_collections ',
'where collection_name = :AI_LOCAL_COLLECTION'))
