wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(231170639121981383593)
,p_plug_name=>'REMOTE Program Options (&AI_REMOTE_ENV.)'
,p_region_name=>'remoteOptions'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:t-Region--hideShowIconsMath:is-expanded:t-Region--accent5:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2664334895415463485
,p_plug_display_sequence=>35
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'     n001    ID',
'    ,APEX_ITEM.CHECKBOX2(1,SEQ_ID,''class="my_checkbox"'',NULL,NULL,''f01_''||SEQ_ID) as select_row',
'    ,n002    app_id',
'    ,c001    app_alias',
'    ,n003    opt_no',
'    ,c002    opt_name ',
'    ,c003    opt_val_varchar',
'    ,n004    opt_val_number',
'    ,c004    opt_val_boolean',
'    ,c005    opt_val_date_formatted ',
'    ,d001    opt_val_date ',
'    ,c006    opt_val_timestamp',
'    ,clob001 opt_val_clob',
'    ,nvl2 ( BLOB001,''* REMOTE Images not Displayed *'',''No Image'') as image',
'    /*  -- since this is REMOTE, there is no local table to resolve the image on the report',
'    , NVL2( BLOB001,',
'            ''<img src="'' || APEX_UTIL.GET_BLOB_FILE_SRC(''P12_OPT_VAL_IMG'', n001) ||',
'            ''" height="100" width="100" />'',',
'            ''No Image'') as image',
'    */            ',
'    ,c008   img_file_name      ',
'    --,to_char( d003, ''MM-DD-YYYY HH:MI:SS pm'') as CREATED',
'    ,D003 as CREATED',
'    ,c012 as CREATED_BY',
'    --,to_char( d004, ''MM-DD-YYYY HH:MI:SS pm'') as UPDATED     ',
'    ,D004 as UPDATED',
'    ,c014 as UPDATED_BY ',
'    ,D005 as EFF_START_DA ',
'  --  ,c015 as eff_end_da  -- ''YYYY-MM-DD"T"HH24:MI:SS"Z"''',
'--    ,to_date(C015, ''YYYY-MM-DD HH24:MI:SS'') as EFF_END_DA -- "VARCHAR" in collection since we only have 5 date columns    ',
'    ,to_date(C015, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'') as EFF_END_DA -- "VARCHAR" in collection since we only have 5 date columns      ',
'from apex_collections ',
'where collection_name = :AI_REMOTE_COLLECTION --''REMOTE_REST_SOURCE_RESULTS''',
'order by n002, c001, n003  -- app_id, app_alias, opt_no'))
,p_plug_source_type=>'NATIVE_IR'
