wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(231178827160316023171)
,p_plug_name=>'LOCAL Program Options (&AI_LOCAL_ENV.)'
,p_region_name=>'localOptions1'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:t-Region--hideShowIconsMath:is-expanded:t-Region--accent4:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2664334895415463485
,p_plug_display_sequence=>15
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'    ID, ',
'    APP_ID,',
'    APP_ALIAS,',
'    OPT_NO,',
'    OPT_NAME,',
'    case when length(OPT_VAL_VARCHAR) > 50',
'      then substr(OPT_VAL_VARCHAR, 1, 50)|| ''<em> ... more</em>''',
'      else OPT_VAL_VARCHAR',
'      end as OPT_VAL_VARCHAR,',
'    OPT_VAL_NUMBER,',
'    OPT_VAL_BOOLEAN,',
'    OPT_VAL_DATE,',
'    OPT_VAL_TIMESTAMP,',
'    dbms_lob.getlength (OPT_VAL_CLOB) as clob_length,',
'    case when dbms_lob.getlength (OPT_VAL_CLOB) > 100',
'      then dbms_lob.substr( OPT_VAL_CLOB, 100, 1 ) || ''<em> ... more</em>''',
'      else dbms_lob.substr( OPT_VAL_CLOB, 100, 1 )',
'      end as OPT_VAL_CLOB,',
'    case when dbms_lob.getlength (OPT_VAL_CLOB) > 100',
'      then dbms_lob.substr( OPT_VAL_CLOB, 100, 1 ) || '' ... more''',
'      else dbms_lob.substr( OPT_VAL_CLOB, 100, 1 )',
'      end as OPT_VAL_CLOB_escaped,          ',
'    CRE_UT,',
'    CRE_PGM_NA,',
'    CRE_UID_CD,',
'    REVSN_UT,',
'    REVSN_PGM_NA,',
'    REVSN_UID_CD,',
'    (select count(*) from APXSHR_PGM_OPT_ALT_OWNR where OPTION_ID = opts.ID ) as alt_owner_count,',
'    dbms_lob.getlength(OPT_VAL_IMG) as image2,  -- "NEW", better way to render images, per documentation',
'    img_file_name,',
'    EFF_START_DA,',
'    EFF_END_DA',
'    /*  -- this is the "OLD" way to render images, required item on form',
'    NVL2(OPT_VAL_IMG,',
'     ''<img src='' || APEX_UTIL.GET_BLOB_FILE_SRC(''P12_OPT_VAL_IMG'',ID) ||',
'     '' height=100 width=100 />'',',
'     ''No Image'') image,',
'    */     ',
'    ',
'from #OWNER#.APXSHR_PGM_OPTIONS opts',
'where app_alias = :P8_APP_ALIAS',
'order by APP_ID, APP_ALIAS, OPT_NO'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P8_APP_ALIAS'
,p_prn_content_disposition=>'ATTACHMENT'
