wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(231173178471802468905)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insert / Update Selected Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Tempted to make this a stored procedure, but there''s too much based on page items ',
'DECLARE',
'    l_update_count NUMBER :=0;',
'    l_insert_count NUMBER :=0;',
'    l_commit_count NUMBER :=0;',
'    l_x            VARCHAR2(10);',
'  ',
'    l_app_id            NUMBER;',
'    l_app_alias         APXSHR_PGM_OPTIONS.APP_ALIAS%TYPE;',
'    l_opt_no            NUMBER;',
'    l_opt_name          APXSHR_PGM_OPTIONS.OPT_NAME%TYPE;',
'    l_opt_val_varchar   APXSHR_PGM_OPTIONS.OPT_VAL_VARCHAR%TYPE;',
'    l_opt_val_number    NUMBER;',
'    l_opt_val_boolean   APXSHR_PGM_OPTIONS.OPT_VAL_BOOLEAN%TYPE;',
'    l_opt_val_date      DATE;',
'    l_opt_val_timestamp TIMESTAMP;',
'    l_opt_val_clob      CLOB;',
'    l_opt_val_img       BLOB;',
'    l_img_mime_type     APXSHR_PGM_OPTIONS.IMG_MIME_TYPE%TYPE;',
'    l_img_file_name     APXSHR_PGM_OPTIONS.IMG_FILE_NAME%TYPE;    ',
'    l_img_char_set      APXSHR_PGM_OPTIONS.IMG_CHAR_SET%TYPE;',
'    l_img_last_upd_da   DATE;',
'    l_eff_start_da      DATE;',
'    l_eff_end_da        DATE;    ',
'',
'BEGIN',
'    FOR I in 1..APEX_APPLICATION.G_F01.COUNT  -- F01 count will be the number of boxes checked',
'    LOOP',
'',
'        begin -- select the option from the COLLECTION  ''YYYY-MM-DD"T"HH24:MI:SS"Z"''',
'            select',
'                N002,     C001,        N003,       C002,       C003,              N004,             C004,              D001,     ',
'--                TO_TIMESTAMP(C006,''YYYY-MM-DD HH24:MI:SS.FF''), CLOB001,           BLOB001,          C007,              C008,                       ',
'                TO_TIMESTAMP(C006,''YYYY-MM-DD"T"HH24:MI:SS"Z"''), CLOB001,           BLOB001,          C007,              C008, ',
'--                C009,                  D002,                   D005,              to_date(C015, ''YYYY-MM-DD HH24:MI:SS'') ',
'                C009,                  D002,                   D005,              to_date(C015, ''YYYY-MM-DD"T"HH24:MI:SS"Z"'')                 ',
'              into',
'                l_app_id, l_app_alias, l_opt_no,   l_opt_name, l_opt_val_varchar, l_opt_val_number, l_opt_val_boolean, l_opt_val_date, ',
'                l_opt_val_timestamp,                           l_opt_val_clob,    l_opt_val_img,    l_img_mime_type,   l_img_file_name,',
'                l_img_char_set,        l_img_last_upd_da,      l_eff_start_da,    l_eff_end_da',
'            from APEX_COLLECTIONS ',
'            where COLLECTION_NAME = :AI_REMOTE_COLLECTION',
'              and SEQ_ID = APEX_APPLICATION.G_F01(I);',
'        end;  -- select',
'        ',
'        begin -- select APXSHR_PGM_OPTIONS row based on value in collection',
'            select ',
'              ''x'' into l_x',
'            from APXSHR_PGM_OPTIONS ',
'            where NVL(APP_ID, -1)      = nvl(l_app_id, -1)',
'              and NVL(APP_ALIAS, ''-1'') = nvl(l_app_alias, ''-1'')',
'              and OPT_NO               = l_opt_no;',
'            ',
'            -- if found, update the row',
'            begin --update',
'                update APXSHR_PGM_OPTIONS',
'                    set opt_name          = l_opt_name,',
'                        opt_val_varchar   = l_opt_val_varchar,',
'                        opt_val_number    = l_opt_val_number,',
'                        opt_val_boolean   = l_opt_val_boolean,',
'                        opt_val_date      = l_opt_val_date,',
'                        opt_val_timestamp = l_opt_val_timestamp,',
'                        opt_val_clob      = l_opt_val_clob,',
'                        opt_val_img       = l_opt_val_img,',
'                        img_mime_type     = l_img_mime_type,',
'                        img_file_name     = l_img_file_name,',
'                        img_char_set      = l_img_char_set,',
'                        img_last_upd_da   = l_img_last_upd_da,',
'                        eff_start_da      = l_eff_start_da,',
'                        eff_end_da        = l_eff_end_da',
'                where NVL(APP_ID, -1)      = nvl(l_app_id, -1)',
'                  and NVL(APP_ALIAS, ''-1'') = nvl(l_app_alias, ''-1'')',
'                  and OPT_NO               = l_opt_no;',
'',
'                l_commit_count := l_commit_count + 1;',
'                l_update_count := l_update_count + 1;',
'                ',
'                -- exception when others then null;',
'            ',
'            end;  --update',
'              ',
'            exception ',
'                when NO_DATA_FOUND  -- if not found, INSERT the row',
'                then',
'                    begin -- insert',
'                        insert into APXSHR_PGM_OPTIONS',
'                            (',
'                             app_id,   app_alias,   opt_no,     opt_name,   opt_val_varchar,   opt_val_number,   opt_val_boolean,',
'                             opt_val_date,   opt_val_timestamp,   opt_val_clob,',
'                             opt_val_img,    img_mime_type,       img_file_name,   img_char_set,   img_last_upd_da,',
'                             eff_start_da,   eff_end_da',
'                             )',
'                        values',
'                            (',
'                             l_app_id, l_app_alias, l_opt_no,   l_opt_name, l_opt_val_varchar, l_opt_val_number, l_opt_val_boolean, ',
'                             l_opt_val_date, l_opt_val_timestamp, l_opt_val_clob,',
'                             l_opt_val_img,  l_img_mime_type,     l_img_file_name, l_img_char_set, l_img_last_upd_da,',
'                             l_eff_start_da, l_eff_end_da',
'                             );',
'                        ',
'                        l_insert_count := l_insert_count + 1;',
'                        l_commit_count := l_commit_count + 1;',
'                        ',
'                        exception when others then NULL;',
'                    end;  -- insert',
'                    ',
'        end;  -- select',
'',
'        if l_commit_count > 25',
'        then',
'            COMMIT;',
'            l_commit_count := 0;',
'        end if;',
'',
'    END LOOP;',
'    ',
'   :P8_ROWS_UPDATED  := to_char(l_update_count,''99,990'');',
'   :P8_ROWS_INSERTED := to_char(l_insert_count,''99,990'');',
'',
'    COMMIT;',
'    ',
'END;  -- anonymous block'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(231173178215093467174)
,p_process_success_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'&P8_ROWS_UPDATED. Option(s) updated.',
'&P8_ROWS_INSERTED. Option(s) inserted.'))
,p_internal_uid=>117081451109618241
);
end;
/
