,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    my_count number := 0;',
'begin',
'    if  :P12_ID IS NOT NULL',
'    then',
'        -- ONLY ALLOW ROW CREATOR OR ADMIN TO DELETE OR CHANGE ACCESS',
'        if :P12_CRE_UID_CD = :APP_USER',
'        or apex_authorization.is_authorized(''access control - edit'') ',
'        then ',
'            return true; ',
'        else',
'            -- allow access if user is an Alt Owner for this ID',
'            begin',
'                select ',
'                    count(*) into my_count ',
'                from APXSHR_PGM_OPT_ALT_OWNR ',
'                where ALT_OWNR_ACF2_LID_ID = :APP_USER ',
'                  and OPTION_ID = :P12_ID;',
'                  ',
'                exception when others then my_count := 0;',
'            end;',
'            ',
'            if my_count = 0',
'            then ',
'                return false;',
'            else',
'                return true;',
'            end if;  ',
'        end if;',
'    else',
'        return false;',
'    end if;',
'end;'))
,p_button_condition2=>'PLSQL'
,p_button_condition_type=>'FUNCTION_BODY'
,p_database_action=>'UPDATE'
);
