wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(231183739823039228584)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Copy Image Data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
'    We have to do this because unless the user picks an image after copying,',
'    the OLD image will NOT be stored on the copied row.',
'',
'    This "forces" the issue and seems to work pretty well.',
'',
'    If the user decides to change the image, the OPT_VAL_IMG will not be null,',
'    and we won''t do the copy from the old row.',
'*/',
'declare',
'    l_opt_record APXSHR_PGM_OPTIONS%ROWTYPE;',
'begin',
'    -- get the PREVIOUS row (including the IMAGE data)',
'    select * into l_opt_record',
'    from APXSHR_PGM_OPTIONS',
'    where ID = :P12_ID_COPY;',
'',
'    -- skip this if user changed the image',
'    if :P12_OPT_VAL_IMG is NULL',
'    then',
'        update APXSHR_PGM_OPTIONS',
'            set OPT_VAL_IMG     = l_opt_record.OPT_VAL_IMG,',
'                IMG_MIME_TYPE   = l_opt_record.IMG_MIME_TYPE,',
'                IMG_FILE_NAME   = l_opt_record.IMG_FILE_NAME,',
'                IMG_CHAR_SET    = l_opt_record.IMG_CHAR_SET,',
'                IMG_LAST_UPD_DA = l_opt_record.IMG_LAST_UPD_DA',
'        where ID = :P12_ID;   ',
'    end if;         ',
'    commit;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(236190126608359579180)
,p_process_when=>'P12_ID_COPY'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>127642802346377920
,p_process_comment=>'Special process needed if we want to copy images from the original rows.'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(236190130531165579192)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SESSION_STATE'
,p_process_name=>'reset page'
,p_attribute_01=>'CLEAR_CACHE_CURRENT_PAGE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(236190126828658579180)
,p_internal_uid=>5134033510472728528
);
wwv_flow_imp_page.create_page_process(
