,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_region_id=>wwv_flow_imp.id(236190126029012579176)
,p_process_type=>'NATIVE_FORM_INIT'
,p_process_name=>'Initialize form Form on APXSHR_PGM_OPTIONS'
,p_internal_uid=>114543860703532946
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(234381879464476505289)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Copy ID & SET P12_ID NULL on COPY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P12_ID_COPY := :P12_ID;  -- used to copy image, if present',
':P12_ID := NULL; -- so Create Button shows'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'COPY'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>3325782443783654625
,p_process_comment=>'Only do this for COPY! Works with a process AFTER the DML page process when the P12_ID_COPY is populated so that we can copy images.'
);
end;
