prompt --application/deployment/install/install_create_apxshr_pgm_options
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(259009146474951508985)
,p_install_id=>wwv_flow_imp.id(259005530448735415855)
,p_name=>'Create APXSHR_PGM_OPTIONS'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  CREATE SEQUENCE  "APXSHR_PGM_OPTIONS_SEQ"  MINVALUE 1 MAXVALUE 99999999999999999999999999 INCREMENT BY 1 START WITH 1 NOCACHE  ORDER  CYCLE  NOKEEP  NOSCALE  GLOBAL ;   ',
'  ',
'  CREATE TABLE "APXSHR_PGM_OPTIONS" ',
'   (	"ID" NUMBER NOT NULL ENABLE, ',
'	"APP_ID" NUMBER, ',
'	"APP_ALIAS" VARCHAR2(100), ',
'	"OPT_NO" NUMBER NOT NULL ENABLE, ',
'	"OPT_NAME" VARCHAR2(100), ',
'	"OPT_VAL_VARCHAR" VARCHAR2(4000), ',
'	"OPT_VAL_NUMBER" NUMBER, ',
'	"OPT_VAL_BOOLEAN" VARCHAR2(5), ',
'	"CRE_UT" DATE NOT NULL ENABLE, ',
'	"CRE_PGM_NA" VARCHAR2(30) NOT NULL ENABLE, ',
'	"CRE_UID_CD" VARCHAR2(255) NOT NULL ENABLE, ',
'	"REVSN_UT" DATE NOT NULL ENABLE, ',
'	"REVSN_PGM_NA" VARCHAR2(30) NOT NULL ENABLE, ',
'	"REVSN_UID_CD" VARCHAR2(255) NOT NULL ENABLE, ',
'	"OPT_VAL_CLOB" CLOB, ',
'	"OPT_VAL_DATE" DATE, ',
'	"OPT_VAL_TIMESTAMP" TIMESTAMP (6), ',
'	"OPT_VAL_IMG" BLOB, ',
'	"IMG_MIME_TYPE" VARCHAR2(255), ',
'	"IMG_FILE_NAME" VARCHAR2(1000), ',
'	"IMG_CHAR_SET" VARCHAR2(255), ',
'	"IMG_LAST_UPD_DA" DATE, ',
'	"EFF_START_DA" DATE, ',
'	"EFF_END_DA" DATE, ',
'	 CONSTRAINT "APXSHR_PGM_OPTIONS_PK" PRIMARY KEY ("ID")',
'  USING INDEX  ENABLE, ',
'	 CONSTRAINT "APXSHR_PGM_OPTIONS_U1" UNIQUE ("APP_ID", "APP_ALIAS", "OPT_NO")',
'  USING INDEX  ENABLE',
'   )  ENABLE ROW MOVEMENT ;',
'',
'  CREATE TABLE "APXSHR_PGM_OPTIONS_HIST" ',
'   (	"AS_OF_DA" DATE NOT NULL ENABLE, ',
'	"APP_ID" NUMBER, ',
'	"APP_ALIAS" VARCHAR2(100), ',
'	"OPT_NO" NUMBER NOT NULL ENABLE, ',
'	"OPT_NAME" VARCHAR2(100), ',
'	"OPT_VAL_VARCHAR" VARCHAR2(4000), ',
'	"OPT_VAL_NUMBER" NUMBER, ',
'	"OPT_VAL_BOOLEAN" VARCHAR2(5), ',
'	"OPT_VAL_CLOB" CLOB, ',
'	"OPT_VAL_DATE" DATE, ',
'	"OPT_VAL_TIMESTAMP" TIMESTAMP (6), ',
'	"OPT_VAL_IMG" BLOB, ',
'	"IMG_MIME_TYPE" VARCHAR2(255), ',
'	"IMG_FILE_NAME" VARCHAR2(1000), ',
'	"IMG_CHAR_SET" VARCHAR2(255), ',
'	"IMG_LAST_UPD_DA" DATE, ',
'	"CRE_UT" DATE NOT NULL ENABLE, ',
'	"CRE_PGM_NA" VARCHAR2(100) NOT NULL ENABLE, ',
'	"CRE_UID_CD" VARCHAR2(100) NOT NULL ENABLE, ',
'	"REVSN_UT" DATE NOT NULL ENABLE, ',
'	"REVSN_PGM_NA" VARCHAR2(100) NOT NULL ENABLE, ',
'	"REVSN_UID_CD" VARCHAR2(100) NOT NULL ENABLE, ',
'	 CONSTRAINT "APXSHR_PGM_OPTIONS_HIST_U1" UNIQUE ("AS_OF_DA", "APP_ID", "APP_ALIAS", "OPT_NO")',
'  USING INDEX  ENABLE',
'   ) ;',
'',
'  CREATE INDEX "APXSHR_PGM_OPTIONS_IDX1" ON "APXSHR_PGM_OPTIONS" ("APP_ALIAS", "OPT_NO") ',
'  ;',
'',
'  CREATE INDEX "APXSHR_PGM_OPTIONS_IDX2" ON "APXSHR_PGM_OPTIONS" ("APP_ID", "OPT_NO") ',
'  ;',
'',
'  CREATE OR REPLACE EDITIONABLE TRIGGER "APXSHR_PGM_OPTIONS_T1" ',
'  before insert on "APXSHR_PGM_OPTIONS"                ',
'  for each row   ',
'begin    ',
'if :NEW."ID" is null then  ',
'  select "APXSHR_PGM_OPTIONS_SEQ".nextval into :NEW."ID" from dual;  ',
'end if;  ',
'if :new.CRE_UID_CD is null then :new.CRE_UID_CD := NVL(v(''APP_USER''),USER); end if;  ',
'if :new.CRE_PGM_NA is null then :new.CRE_PGM_NA := ''Apex App: ''||v(''APP_ID''); end if; ',
'if :new.CRE_UT is null then select SYSDATE into :new.CRE_UT from dual; end if;  ',
'if :new.REVSN_UID_CD is null then :new.REVSN_UID_CD := NVL(v(''APP_USER''),USER); end if;  ',
'if :new.REVSN_PGM_NA is null then :new.REVSN_PGM_NA := ''Apex App: ''||v(''APP_ID''); end if; ',
'if :new.REVSN_UT is null then select SYSDATE into :new.REVSN_UT from dual; end if;  ',
'end;',
'/',
'ALTER TRIGGER "APXSHR_PGM_OPTIONS_T1" ENABLE;',
'  CREATE OR REPLACE EDITIONABLE TRIGGER "APXSHR_PGM_OPTIONS_T2" ',
'BEFORE ',
'update on "APXSHR_PGM_OPTIONS" ',
'for each row ',
'begin ',
'  if (:new.REVSN_UID_CD = :old.REVSN_UID_CD) OR (:new.REVSN_UID_CD IS NULL) then :new.REVSN_UID_CD := NVL(v(''APP_USER''),USER); end if; ',
'  if (:new.REVSN_PGM_NA = :old.REVSN_PGM_NA) OR (:new.REVSN_PGM_NA IS NULL) then :new.REVSN_PGM_NA := ''Apex App: ''||v(''APP_ID''); end if; ',
'  if (:new.REVSN_UT = :old.REVSN_UT) OR (:new.REVSN_UT IS NULL) then select SYSDATE into :new.REVSN_UT from dual; end if; ',
'END;',
'/',
'ALTER TRIGGER "APXSHR_PGM_OPTIONS_T2" ENABLE;',
'',
'  CREATE INDEX "APXSHR_PGM_OPTIONS_HIST_IDX1" ON "APXSHR_PGM_OPTIONS_HIST" ("AS_OF_DA", "APP_ALIAS", "OPT_NO") ',
'  ;',
'',
'  CREATE INDEX "APXSHR_PGM_OPTIONS_HIST_IDX2" ON "APXSHR_PGM_OPTIONS_HIST" ("AS_OF_DA", "APP_ID", "OPT_NO") ',
'  ;',
'',
'  CREATE OR REPLACE EDITIONABLE TRIGGER "APXSHR_PGM_OPTIONS_HIST_T1" ',
'  before insert on "APXSHR_PGM_OPTIONS_HIST"                  ',
'  for each row     ',
'begin      ',
'    if :new.CRE_UID_CD is null then :new.CRE_UID_CD := NVL(v(''APP_USER''),USER); end if;    ',
'    if :new.CRE_PGM_NA is null then :new.CRE_PGM_NA := ''Apex App: ''||v(''APP_ID''); end if;   ',
'    if :new.CRE_UT is null then select SYSDATE into :new.CRE_UT from dual; end if;    ',
'       ',
'    if :new.REVSN_UID_CD is null then :new.REVSN_UID_CD := NVL(v(''APP_USER''),USER); end if;    ',
'    if :new.REVSN_PGM_NA is null then :new.REVSN_PGM_NA := ''Apex App: ''||v(''APP_ID''); end if;   ',
'    if :new.REVSN_UT is null then select SYSDATE into :new.REVSN_UT from dual; end if;       ',
'end;',
'/',
'ALTER TRIGGER "APXSHR_PGM_OPTIONS_HIST_T1" ENABLE; '))
);
wwv_flow_imp_shared.create_install_object(
 p_id=>wwv_flow_imp.id(259009146610269508987)
,p_script_id=>wwv_flow_imp.id(259009146474951508985)
,p_object_owner=>'#OWNER#'
,p_object_type=>'TABLE'
,p_object_name=>'APXSHR_PGM_OPTIONS'
);
wwv_flow_imp_shared.create_install_object(
 p_id=>wwv_flow_imp.id(259009146741894508989)
,p_script_id=>wwv_flow_imp.id(259009146474951508985)
,p_object_owner=>'#OWNER#'
,p_object_type=>'TABLE'
,p_object_name=>'APXSHR_PGM_OPTIONS_HIST'
);
end;
