prompt --application/deployment/install/install_create_apxshr_pgm_opt_alt_ownr
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(259009743778033229334)
,p_install_id=>wwv_flow_imp.id(259005530448735415855)
,p_name=>'Create APXSHR_PGM_OPT_ALT_OWNR'
,p_sequence=>20
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  CREATE TABLE "APXSHR_PGM_OPT_ALT_OWNR" ',
'   (	"ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 61 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, ',
'	"OPTION_ID" NUMBER NOT NULL ENABLE, ',
'	"ALT_OWNR_ACF2_LID_ID" VARCHAR2(11 CHAR) NOT NULL ENABLE, ',
'	"CREATED" DATE NOT NULL ENABLE, ',
'	"CREATED_BY" VARCHAR2(255 CHAR) NOT NULL ENABLE, ',
'	"UPDATED" DATE NOT NULL ENABLE, ',
'	"UPDATED_BY" VARCHAR2(255 CHAR) NOT NULL ENABLE',
'   ) ;',
'  CREATE UNIQUE INDEX "APXSHR_PGM_OPT_ALT_OWNR_PK" ON "APXSHR_PGM_OPT_ALT_OWNR" ("ID") ',
'  ;',
'  CREATE UNIQUE INDEX "APXSHR_PGM_OPT_ALT_OWNR_U1" ON "APXSHR_PGM_OPT_ALT_OWNR" ("OPTION_ID", "ALT_OWNR_ACF2_LID_ID") ',
'  ;',
'ALTER TABLE "APXSHR_PGM_OPT_ALT_OWNR" ADD CONSTRAINT "APXSHR_PGM_OPT_ALT_OWNR_PK" PRIMARY KEY ("ID")',
'  USING INDEX "APXSHR_PGM_OPT_ALT_OWNR_PK"  ENABLE;',
'ALTER TABLE "APXSHR_PGM_OPT_ALT_OWNR" ADD CONSTRAINT "APXSHR_PGM_OPT_ALT_OWNR_U1" UNIQUE ("OPTION_ID", "ALT_OWNR_ACF2_LID_ID")',
'  USING INDEX "APXSHR_PGM_OPT_ALT_OWNR_U1"  ENABLE;',
'',
'  ALTER TABLE "APXSHR_PGM_OPT_ALT_OWNR" ADD CONSTRAINT "APXSHR_PGM_OPT_ALT_OWNR_FK" FOREIGN KEY ("OPTION_ID")',
'	  REFERENCES "APXSHR_PGM_OPTIONS" ("ID") ON DELETE CASCADE ENABLE;',
'',
'  CREATE INDEX "APXSHR_PGM_OPT_ALT_OWNR_I1" ON "APXSHR_PGM_OPT_ALT_OWNR" ("OPTION_ID") ',
'  ;',
'',
'   COMMENT ON COLUMN "APXSHR_PGM_OPT_ALT_OWNR"."ALT_OWNR_ACF2_LID_ID" IS ''alternate owner for the referenced option'';',
'   COMMENT ON TABLE "APXSHR_PGM_OPT_ALT_OWNR"  IS ''child table of apxshr_pgm_options allows from multiple owners of options.'';',
'',
'  CREATE OR REPLACE EDITIONABLE TRIGGER "APXSHR_PGM_OPT_ALT_OWNR_BIU" ',
'    before insert or update   ',
'    on apxshr_pgm_opt_alt_ownr  ',
'    for each row ',
'begin  ',
'    if inserting then  ',
'        :new.created := sysdate;  ',
'        :new.created_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);  ',
'    end if;  ',
'    :new.updated := sysdate;  ',
'    :new.updated_by := coalesce(sys_context(''APEX$SESSION'',''APP_USER''),user);  ',
'end apxshr_pgm_opt_alt_ownr_biu;',
'/',
'ALTER TRIGGER "APXSHR_PGM_OPT_ALT_OWNR_BIU" ENABLE; '))
);
