prompt --application/deployment/install/install_create_rest_service
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(259369057631554162637)
,p_install_id=>wwv_flow_imp.id(259005530448735415855)
,p_name=>'Create REST Service'
,p_sequence=>50
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
'    !!! NOTE:  You will need to change the p_url_mapping_pattern value to match your TARGET schema alias.  !!!',
'    See lines 18 & 19 below.  You MAY also have to disable RESTful Access for the Target ORDS schema prior to running this (and then re-enable it).',
'*/',
'-- Generated by ORDS REST Data Services 25.2.0.r1651520',
'-- Schema: WKSP_SDVLOWCODE  Date: Fri Sep 19 08:21:39 2025 ',
'--',
'',
'        ',
'DECLARE',
'  l_roles     OWA.VC_ARR;',
'  l_modules   OWA.VC_ARR;',
'  l_patterns  OWA.VC_ARR;',
'',
'BEGIN',
'  ORDS.ENABLE_SCHEMA(',
'      p_enabled             => TRUE,',
'      p_url_mapping_type    => ''BASE_PATH'',',
'      -- set the value of p_url_mapping_pattern to match YOUR Parsing Schema ALIAS',
